import React, { useContext, useState } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import MyContext from '../contexts/MyContext';
import './css/LoginComponent.css';

const roleHome = {
  admin: '/admin/report',
  receptionist: '/admin/reception',
  kitchen: '/admin/kitchen',
  customer: '/admin/customer-portal'
};

function Login() {
  const context = useContext(MyContext);
  const navigate = useNavigate();
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmit = async (event) => {
    event.preventDefault();
    setError('');

    if (!username.trim() || !password) {
      setError('Vui lòng nhập tên đăng nhập và mật khẩu.');
      return;
    }

    setIsSubmitting(true);
    try {
      const response = await axios.post('/api/admin/login', {
        username: username.trim(),
        password
      });
      const { token, role, username: accountName } = response.data || {};

      if (!token || !roleHome[role]) {
        setError(response.data?.message || 'Máy chủ trả về thông tin đăng nhập không hợp lệ.');
        return;
      }

      context.signIn({ token, role, username: accountName || username.trim() });
      navigate(roleHome[role], { replace: true });
    } catch (requestError) {
      setError(
        requestError.response?.data?.message ||
        'Không thể kết nối đến máy chủ. Vui lòng kiểm tra máy chủ rồi thử lại.'
      );
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <main style={{ width: 'min(360px, calc(100% - 32px))', margin: '64px auto', textAlign: 'center' }}>
      <h2>ĐĂNG NHẬP HỆ THỐNG</h2>
      <form onSubmit={handleSubmit}>
        <div style={{ marginBottom: '12px' }}>
          <input
            type="text"
            autoComplete="username"
            placeholder="Tên đăng nhập hoặc số điện thoại"
            value={username}
            onChange={(event) => setUsername(event.target.value)}
            style={{ boxSizing: 'border-box', width: '100%', padding: '10px' }}
          />
        </div>
        <div style={{ marginBottom: '12px' }}>
          <input
            type="password"
            autoComplete="current-password"
            placeholder="Mật khẩu"
            value={password}
            onChange={(event) => setPassword(event.target.value)}
            style={{ boxSizing: 'border-box', width: '100%', padding: '10px' }}
          />
        </div>
        {error && <p role="alert" style={{ color: '#b42318' }}>{error}</p>}
        <button type="submit" disabled={isSubmitting} style={{ padding: '10px 24px' }}>
          {isSubmitting ? 'ĐANG ĐĂNG NHẬP…' : 'ĐĂNG NHẬP'}
        </button>
      </form>
    </main>
  );
}

export default Login;
